const input = $input.first().json || {};
const body = input.body || input;

const userPrompt = (body.userPrompt || '').toString().trim();
if (!userPrompt) {
  return [{ json: { validationError: true, errorMessage: 'userPrompt is required but was empty or missing.' } }];
}

const systemPromptCaller = (body.systemPrompt || '').toString();
// Lightweight guardrail applied to every call. Callers can still pass their own systemPrompt above this.
const commonGuardrail = '\n\n[Guardrail] Clearly separate facts from speculation. Do not state uncertain information as fact, and do not invent names, statistics, or sources that were not provided.';
const systemPrompt = (systemPromptCaller + commonGuardrail).trim();

const model = (body.model || 'claude-sonnet-5').toString();
const maxTokens = Number.isFinite(body.maxTokens) ? body.maxTokens : 4000;
const temperature = Number.isFinite(body.temperature) ? body.temperature : 1;

return [{ json: { validationError: false, systemPrompt, userPrompt, model, maxTokens, temperature } }];

const d = $input.first().json;

const body = {
  model: d.model,
  max_tokens: d.maxTokens,
  temperature: d.temperature,
  messages: [
    { role: 'user', content: d.userPrompt }
  ]
};
if (d.systemPrompt) {
  body.system = d.systemPrompt;
}

return [{ json: body }];

const resp = $input.first().json;
const textBlock = (resp.content || []).find(b => b.type === 'text');
const text = (textBlock && textBlock.text) || '';

return [{
  json: {
    success: true,
    text,
    model: resp.model || null,
    stopReason: resp.stop_reason || null,
    usage: resp.usage || null
  }
}];

const generated = $('Format success response').first().json;
const config = $input.first().json;

const preview = (generated.text || '').slice(0, 500);

return [{
  json: {
    slackWebhookUrl: config.slackWebhookUrl,
    slackRequestBody: { text: `New response generated via Claude:\n${preview}` }
  }
}];

const err = $input.first().json.error || $input.first().json;
const detail = typeof err === 'string' ? err : JSON.stringify(err);
return [{ json: { success: false, error: 'Claude API call failed after retries.', detail } }];
